practiceProblems.solutionCode:
public class Main {
    public static String toCsv(String[] items) {
        String result = "";
        for (int i = 0; i < items.length; i++) {
            if (i > 0) {
                result += ", ";
            }
            result += items[i];
        }
        return result;
    }

    public static void main(String[] args) {
        String[] items = {"apple", "banana", "cherry"};
        System.out.println(toCsv(items));
    }
}

