public class Main {
    public static int countAdjacentPairs(int[] arr) {
        int count = 0;
        for (int i = 0; i < arr.length - 1; i++) {
            if (arr[i] == arr[i + 1]) {
                count++;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        int[] data = {1, 2, 2, 3, 3, 3, 4};
        System.out.println("Adjacent Equal Pairs: " + countAdjacentPairs(data));
    }
}
